-- ==============================================================================
-- V1__baseline.sql — schéma source du suivi scolaire (19 tables, 7 vues)
--
-- Reproduit le schéma PostgreSQL fourni : colonnes, clés primaires, clés
-- étrangères, contraintes UNIQUE et CHECK. Les identifiants entiers utilisent
-- GENERATED BY DEFAULT AS IDENTITY (compatible avec les données de démo qui
-- fixent parfois leurs identifiants).
--
-- NE JAMAIS MODIFIER CETTE MIGRATION (baseline Flyway).
-- ==============================================================================

CREATE TABLE annee_scolaire (
    id_annee integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle character varying NOT NULL,
    date_debut date NOT NULL,
    date_fin date NOT NULL,
    seuil_alerte_absences integer NOT NULL,
    CONSTRAINT annee_scolaire_libelle_key UNIQUE (libelle),
    CONSTRAINT ck_annee_dates CHECK (date_fin > date_debut),
    CONSTRAINT annee_scolaire_seuil_alerte_absences_check CHECK (seuil_alerte_absences > 0)
);

CREATE TABLE niveau (
    id_niveau integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle character varying NOT NULL,
    code character varying NOT NULL,
    CONSTRAINT niveau_libelle_key UNIQUE (libelle),
    CONSTRAINT niveau_code_key UNIQUE (code)
);

CREATE TABLE classe (
    id_classe integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom character varying NOT NULL,
    id_annee integer NOT NULL,
    id_niveau integer NOT NULL,
    CONSTRAINT uq_classe_annee_nom UNIQUE (id_annee, nom),
    CONSTRAINT fk_classe_annee FOREIGN KEY (id_annee) REFERENCES annee_scolaire (id_annee),
    CONSTRAINT fk_classe_niveau FOREIGN KEY (id_niveau) REFERENCES niveau (id_niveau)
);

CREATE TABLE eleve (
    id_eleve integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom character varying NOT NULL,
    prenom character varying NOT NULL,
    date_naissance date NOT NULL
);

CREATE TABLE inscription (
    id_inscription integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_inscription date NOT NULL,
    id_eleve integer NOT NULL,
    id_classe integer NOT NULL,
    numero_inscription character varying NOT NULL,
    CONSTRAINT inscription_numero_inscription_key UNIQUE (numero_inscription),
    CONSTRAINT fk_inscription_eleve FOREIGN KEY (id_eleve) REFERENCES eleve (id_eleve),
    CONSTRAINT fk_inscription_classe FOREIGN KEY (id_classe) REFERENCES classe (id_classe)
);

CREATE TABLE matiere (
    id_matiere integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle character varying NOT NULL,
    code character varying NOT NULL,
    CONSTRAINT matiere_libelle_key UNIQUE (libelle),
    CONSTRAINT matiere_code_key UNIQUE (code)
);

CREATE TABLE professeur (
    id_professeur integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom character varying NOT NULL,
    prenom character varying NOT NULL
);

CREATE TABLE enseignement (
    id_enseignement integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_classe integer NOT NULL,
    id_matiere integer NOT NULL,
    id_professeur integer NOT NULL,
    CONSTRAINT uq_enseignement_classe_matiere UNIQUE (id_classe, id_matiere),
    CONSTRAINT fk_enseignement_classe FOREIGN KEY (id_classe) REFERENCES classe (id_classe),
    CONSTRAINT fk_enseignement_matiere FOREIGN KEY (id_matiere) REFERENCES matiere (id_matiere),
    CONSTRAINT fk_enseignement_professeur FOREIGN KEY (id_professeur) REFERENCES professeur (id_professeur)
);

CREATE TABLE type_evaluation (
    id_type_eval integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle character varying NOT NULL,
    poids numeric NOT NULL,
    CONSTRAINT type_evaluation_libelle_key UNIQUE (libelle),
    CONSTRAINT type_evaluation_poids_check CHECK (poids > 0)
);

CREATE TABLE trimestre (
    id_trimestre integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero smallint NOT NULL,
    date_debut date NOT NULL,
    date_fin date NOT NULL,
    id_annee integer NOT NULL,
    CONSTRAINT uq_trimestre_annee_numero UNIQUE (id_annee, numero),
    CONSTRAINT trimestre_numero_check CHECK (numero >= 1 AND numero <= 3),
    CONSTRAINT ck_trimestre_dates CHECK (date_fin > date_debut),
    CONSTRAINT fk_trimestre_annee FOREIGN KEY (id_annee) REFERENCES annee_scolaire (id_annee)
);

CREATE TABLE note (
    id_note integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    valeur numeric NOT NULL,
    numero_trimestre smallint NOT NULL,
    id_type_eval integer NOT NULL,
    id_enseignement integer NOT NULL,
    numero_inscription character varying NOT NULL,
    CONSTRAINT note_valeur_check CHECK (valeur >= 0 AND valeur <= 20),
    CONSTRAINT note_numero_trimestre_check CHECK (numero_trimestre >= 1 AND numero_trimestre <= 3),
    CONSTRAINT fk_note_type_eval FOREIGN KEY (id_type_eval) REFERENCES type_evaluation (id_type_eval),
    CONSTRAINT fk_note_enseignement FOREIGN KEY (id_enseignement) REFERENCES enseignement (id_enseignement)
);

CREATE TABLE coefficient (
    id_coefficient integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    valeur numeric NOT NULL,
    id_matiere integer NOT NULL,
    code_niveau character varying NOT NULL,
    CONSTRAINT uq_coefficient_matiere_niveau UNIQUE (id_matiere, code_niveau),
    CONSTRAINT coefficient_valeur_check CHECK (valeur > 0),
    CONSTRAINT fk_coefficient_matiere FOREIGN KEY (id_matiere) REFERENCES matiere (id_matiere)
);

CREATE TABLE salle (
    id_salle integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom character varying NOT NULL,
    capacite integer NOT NULL,
    CONSTRAINT salle_nom_key UNIQUE (nom),
    CONSTRAINT salle_capacite_check CHECK (capacite > 0)
);

CREATE TABLE cours (
    id_cours integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    debut_cours timestamp without time zone NOT NULL,
    fin_cours timestamp without time zone NOT NULL,
    id_enseignement integer NOT NULL,
    id_salle integer NOT NULL,
    CONSTRAINT ck_cours_creneau CHECK (fin_cours > debut_cours AND fin_cours::date = debut_cours::date),
    CONSTRAINT fk_cours_enseignement FOREIGN KEY (id_enseignement) REFERENCES enseignement (id_enseignement),
    CONSTRAINT fk_cours_salle FOREIGN KEY (id_salle) REFERENCES salle (id_salle)
);

CREATE TABLE absence (
    id_absence integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    justifiee boolean DEFAULT false NOT NULL,
    motif character varying,
    id_cours integer NOT NULL,
    numero_inscription character varying NOT NULL,
    CONSTRAINT uq_absence_inscription_cours UNIQUE (numero_inscription, id_cours),
    CONSTRAINT fk_absence_cours FOREIGN KEY (id_cours) REFERENCES cours (id_cours)
);

CREATE TABLE amenagement (
    id_amenagement integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle character varying NOT NULL,
    majoration_temps numeric,
    est_dispense boolean NOT NULL,
    code_matiere character varying,
    CONSTRAINT amenagement_libelle_key UNIQUE (libelle),
    CONSTRAINT amenagement_majoration_temps_check CHECK (majoration_temps > 0),
    CONSTRAINT ck_amenagement_type CHECK (
        (est_dispense AND code_matiere IS NOT NULL AND majoration_temps IS NULL)
        OR ((NOT est_dispense) AND code_matiere IS NULL AND majoration_temps IS NOT NULL)
    )
);

CREATE TABLE attribution_amenagement (
    id_attribution integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_debut date NOT NULL,
    date_fin date,
    id_eleve integer NOT NULL,
    id_amenagement integer NOT NULL,
    CONSTRAINT ck_attribution_dates CHECK (date_fin IS NULL OR date_fin >= date_debut),
    CONSTRAINT fk_attribution_eleve FOREIGN KEY (id_eleve) REFERENCES eleve (id_eleve),
    CONSTRAINT fk_attribution_amenagement FOREIGN KEY (id_amenagement) REFERENCES amenagement (id_amenagement)
);

CREATE TABLE bulletin (
    id_bulletin integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    appreciation_generale text,
    numero_trimestre smallint NOT NULL,
    id_inscription integer NOT NULL,
    CONSTRAINT uq_bulletin_inscription_trimestre UNIQUE (id_inscription, numero_trimestre),
    CONSTRAINT bulletin_numero_trimestre_check CHECK (numero_trimestre >= 1 AND numero_trimestre <= 3),
    CONSTRAINT fk_bulletin_inscription FOREIGN KEY (id_inscription) REFERENCES inscription (id_inscription)
);

CREATE TABLE ligne_bulletin (
    id_ligne integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    appreciation text,
    id_bulletin integer NOT NULL,
    code_matiere character varying NOT NULL,
    CONSTRAINT uq_ligne_bulletin_matiere UNIQUE (id_bulletin, code_matiere),
    CONSTRAINT fk_ligne_bulletin FOREIGN KEY (id_bulletin) REFERENCES bulletin (id_bulletin)
);

-- ══════════════════════════════════════════════════════════════════════════════
--  VUES (lecture seule, jamais mappées comme entités JPA)
-- ══════════════════════════════════════════════════════════════════════════════

-- Moyenne pondérée par matière : poids du type d'évaluation (F17).
CREATE VIEW v_moyenne_matiere AS
SELECT i.id_inscription,
       n.numero_trimestre,
       e.id_enseignement,
       e.id_matiere,
       ROUND(SUM(n.valeur * te.poids) / NULLIF(SUM(te.poids), 0), 2) AS moyenne_matiere
FROM note n
JOIN inscription i ON i.numero_inscription = n.numero_inscription
JOIN enseignement e ON e.id_enseignement = n.id_enseignement
JOIN type_evaluation te ON te.id_type_eval = n.id_type_eval
GROUP BY i.id_inscription, n.numero_trimestre, e.id_enseignement, e.id_matiere;

-- Moyenne générale : moyennes par matière pondérées par le coefficient du
-- niveau de la classe (table coefficient du schéma source, F18).
CREATE VIEW v_moyenne_generale AS
SELECT vm.id_inscription,
       vm.numero_trimestre,
       ROUND(SUM(vm.moyenne_matiere * co.valeur) / NULLIF(SUM(co.valeur), 0), 2) AS moyenne_generale
FROM v_moyenne_matiere vm
JOIN inscription i ON i.id_inscription = vm.id_inscription
JOIN classe c ON c.id_classe = i.id_classe
JOIN niveau n ON n.id_niveau = c.id_niveau
JOIN coefficient co ON co.id_matiere = vm.id_matiere AND co.code_niveau = n.code
GROUP BY vm.id_inscription, vm.numero_trimestre;

-- Rang densifié des élèves d'une classe (ex æquo = même rang, rang suivant décalé, F19).
CREATE VIEW v_rang_classe AS
SELECT i.id_inscription,
       vg.numero_trimestre,
       i.id_classe,
       vg.moyenne_generale,
       RANK() OVER (PARTITION BY i.id_classe, vg.numero_trimestre
                    ORDER BY vg.moyenne_generale DESC) AS rang
FROM v_moyenne_generale vg
JOIN inscription i ON i.id_inscription = vg.id_inscription;

-- Bulletins enrichis de la moyenne générale et du rang (F19).
CREATE VIEW v_bulletin AS
SELECT b.id_bulletin,
       b.id_inscription,
       b.numero_trimestre,
       vg.moyenne_generale,
       rc.rang,
       b.appreciation_generale
FROM bulletin b
LEFT JOIN v_moyenne_generale vg ON vg.id_inscription = b.id_inscription
                               AND vg.numero_trimestre = b.numero_trimestre
LEFT JOIN v_rang_classe rc ON rc.id_inscription = b.id_inscription
                          AND rc.numero_trimestre = b.numero_trimestre;

-- Lignes de bulletin enrichies de la moyenne par enseignement (F17).
CREATE VIEW v_ligne_bulletin AS
SELECT lb.id_ligne,
       lb.id_bulletin,
       e.id_enseignement,
       e.id_matiere,
       e.id_professeur,
       vm.moyenne_matiere,
       lb.appreciation
FROM ligne_bulletin lb
JOIN bulletin b ON b.id_bulletin = lb.id_bulletin
JOIN inscription i ON i.id_inscription = b.id_inscription
JOIN enseignement e ON e.id_classe = i.id_classe
JOIN matiere mat ON mat.id_matiere = e.id_matiere AND mat.code = lb.code_matiere
LEFT JOIN v_moyenne_matiere vm ON vm.id_inscription = i.id_inscription
                             AND vm.numero_trimestre = b.numero_trimestre
                             AND vm.id_enseignement = e.id_enseignement;

-- Enseignements sans coefficient pour le niveau de la classe (contrôle de complétude).
CREATE VIEW v_coefficient_manquant AS
SELECT e.id_enseignement,
       e.id_classe,
       e.id_matiere,
       c.id_niveau
FROM enseignement e
JOIN classe c ON c.id_classe = e.id_classe
JOIN niveau n ON n.id_niveau = c.id_niveau
LEFT JOIN coefficient co ON co.id_matiere = e.id_matiere AND co.code_niveau = n.code
WHERE co.id_coefficient IS NULL;

-- Absences non justifiées dépassant le seuil de l'année scolaire.
CREATE VIEW v_absences_a_signaler AS
SELECT i.id_inscription,
       i.id_eleve,
       COUNT(*) AS nb_absences_non_justifiees,
       a.seuil_alerte_absences
FROM absence ab
JOIN inscription i ON i.numero_inscription = ab.numero_inscription
JOIN classe c ON c.id_classe = i.id_classe
JOIN annee_scolaire a ON a.id_annee = c.id_annee
WHERE NOT ab.justifiee
GROUP BY i.id_inscription, i.id_eleve, a.seuil_alerte_absences
HAVING COUNT(*) >= a.seuil_alerte_absences;
